# Simplified BPE merge step
def most_frequent_pair(corpus):
    counts = {}
    for word in corpus:
        for i in range(len(word) - 1):
            pair = (word[i], word[i+1])
            counts[pair] = counts.get(pair, 0) + 1
    return max(counts, key=counts.get)

corpus = [
    ["l", "o", "w"],
    ["l", "o", "w", "e", "r"],
    ["n", "e", "w"],
    ["w", "i", "d", "e", "s", "t"],
]
pair = most_frequent_pair(corpus)
print(f"Most frequent pair: {pair}")
# ('l', 'o') likely — merge into a single token

