# A minimal BPE trainer
def train_bpe(corpus, num_merges=10):
    # Initialize vocabulary with characters
    vocab = set()
    for word in corpus:
        for c in word:
            vocab.add(c)

    words = [list(w) for w in corpus]
    merges = []

    for _ in range(num_merges):
        counts = {}
        for w in words:
            for i in range(len(w) - 1):
                pair = (w[i], w[i+1])
                counts[pair] = counts.get(pair, 0) + 1

        if not counts:
            break
        pair = max(counts, key=counts.get)
        merges.append(pair)

        # Apply the merge
        new_words = []
        for w in words:
            new_w = []
            i = 0
            while i < len(w):
                if i < len(w) - 1 and (w[i], w[i+1]) == pair:
                    new_w.append(w[i] + w[i+1])
                    i += 2
                else:
                    new_w.append(w[i])
                    i += 1
            new_words.append(new_w)
        words = new_words

    return merges, words

corpus = ["low", "lower", "newest", "widest"]
merges, final = train_bpe(corpus, num_merges=5)
print("Merges:", merges)
print("Final words:", final)
